const RECOVERY_GUIDE = {"source": "ST0x-Technology/st0x.liquidity dashboard/src/lib/transfer.ts RECOVERY_GUIDE, same commit as this file; regenerate from there, do not edit by hand", "modeLabels": {"requires-bot": "REST \u2014 requires the running bot", "direct-db": "direct DB \u2014 stop the bot / ensure it is not driving this id"}, "groups": [{"object": "transfer", "commands": [{"command": "st0x-liquidity-client --env production debug recheck <mint|redemption|usdc> <id>", "description": "Re-poll the provider and complete the transfer if it has settled.", "whenToUse": "A transfer is stuck or failed but the provider may have settled it.", "appliesTo": "Equity mint / redemption (any non-completed state), failed Base to Alpaca USDC deposit with an onchain deposit transaction. A failed Alpaca to Base deposit needs manual settlement, then reconcile-usdc.", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug resume", "description": "Re-drive ALL interrupted mints and redemptions (no id; best-effort per transfer, failures reported as counts).", "whenToUse": "Equity transfers were interrupted mid-flight and need re-driving via the bot.", "appliesTo": "All in-flight equity transfers", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug resume-usdc <alpaca-to-base|base-to-alpaca> <id>", "description": "Re-drive a single USDC bridge on the bot's transfer worker.", "whenToUse": "A USDC bridge stopped mid-flight, before or after the burn. For an Alpaca to Base bridge at converting, first confirm at Alpaca that no USD to USDC order for the transfer is still open: the resume can fail it without asking Alpaca (see its transfer dialog).", "appliesTo": "USDC bridge (in-flight)", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug fail-equity-transfer <mint|redemption> <id> --reason \"<reason>\"", "description": "Force a stuck transfer into the terminal Failed state.", "whenToUse": "A mint/redemption is permanently stuck and unrecoverable.", "appliesTo": "Equity mint / redemption (non-terminal)", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug fail-usdc-transfer <id> --reason \"<reason>\"", "description": "Force a USDC bridge stuck before its burn into Failed. Alpaca to Base: the bot accepts this only before the burn, from a completed withdrawal or a burn submission with no recorded burn, and it does not check the chain. A burn the bot sent but did not record can still land, so do not fail the transfer until you have done every check and the nonce close on Ethereum in docs/cli-ops.md, \"Clearing a pre-burn guard latch\", with the bot stopped. Then fail it with the offline stox fail-usdc-transfer before you start the bot again: a restart sends the burn of a completed withdrawal (at a burn submission, this command after a restart works too). If a burn landed or you are not certain, run resume-usdc instead. The funds left Alpaca, so the guard stays held until you settle them with reconcile-usdc. Base to Alpaca: the bot accepts this only while the vault withdrawal is unrecorded, and it does not check the chain. First confirm on Base that the bot wallet made no OperatorWithdraw on the inventory after the transfer's from_block, and no WithdrawV2 on the orderbook either (a withdrawal sent before the inventory migration). Only a USDC withdrawal from the cash vault counts: its vaultId equals the cash vault_id in the bot config, and the bot wallet is the OperatorWithdraw operator or the WithdrawV2 sender. A WithdrawV2 with the inventory as sender does not count. A withdraw the network accepted but has not mined is not in the logs yet, so also wait until the transfer's attempt timeout has passed and confirm the wallet has no pending transaction (no pending withdraw4, pending nonce equals latest nonce on more than one RPC provider, and the explorer shows no queued transaction from the wallet). A queued transaction waits behind a nonce gap: with the bot stopped, fill each empty nonce below it, in order, with a self-transfer as below, after making sure no send the bot signed and keeps holds that nonce, then repeat the checks. These checks cannot prove that nothing is pending. If a withdrawal landed or you are not certain, run resume-usdc instead: it adopts a withdrawal of the full amount, and any other amount ends the transfer in WithdrawalFailed, so move that USDC from the bot wallet back to the cash vault by hand. If nothing landed, the resume keeps redriving: repeat the checks, and once every check is clean, take the next step. If none landed, close the nonce before you fail the transfer: stop the bot, check again that the wallet has no pending or queued transaction, make sure no send the bot signed and keeps holds that nonce (if one does, start the bot so it rebroadcasts the send instead), send a 0-value transfer with no calldata from the bot wallet to itself at the latest nonce, with maxFeePerGas and maxPriorityFeePerGas well above the market fee, wait for its required confirmations, and check the withdrawal logs again. The self-transfer closes only that nonce. If a withdrawal mined instead, a transaction is pending or queued, or you cannot tell, start the bot and run resume-usdc, and do not fail the transfer. Otherwise run the offline stox fail-usdc-transfer, or this command after you restart the bot. If a withdrawal for this transfer mines later anyway, move its USDC from the bot wallet back to the cash vault by hand. While a recorded withdrawal is still confirming, run resume-usdc. Once it has confirmed the bot refuses: do every check and the nonce close on Base in docs/cli-ops.md, \"Clearing a pre-burn guard latch\". If a burn landed, something is pending or queued, or you are not certain, start the bot and run resume-usdc, and do not fail the transfer. Otherwise run the offline stox fail-usdc-transfer and move the wallet USDC back by hand. If a burn for this transfer mines later anyway, resume and reconcile refuse the failed transfer. Keep the bot stopped until that USDC is at Alpaca: the offline commands send from the bot wallet and replace whatever is pending at their nonce. Mint it with stox cctp complete-mint --burn-tx <burn> --source-chain base (it adopts a relayer's mint; do not mint by hand, since the MessageSent log holds a placeholder nonce). Then send the amount received that complete-mint printed, divided by 1,000,000 (it prints USDC base units), to Alpaca with stox alpaca-deposit -a <amount>, and do not move that USDC back to the vault. Once Alpaca credits it, convert it with stox alpaca-convert -d to-usd -a <amount>, as the bot would have.", "whenToUse": "A USDC bridge is stuck before its CCTP burn and must be terminalized. Run the check for its direction in the description first; if it is not certain, run resume-usdc.", "appliesTo": "USDC bridge (pre-burn stuck)", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug reconcile-equity <mint|redemption> <id> --reason \"<reason>\"", "description": "Mark a terminally-failed equity transfer Reconciled after handling residue manually. For a redemption that failed at detection or was rejected before the bot started, its amount stays in flight until the next restart.", "whenToUse": "An equity transfer is in a terminal failure and its residue was settled out-of-band (bookkeeping).", "appliesTo": "Failed equity mint / redemption", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug reconcile-usdc <id> --reason <funds-moved-manually|deposit-credited-offline>", "description": "Mark a failed USDC bridge Reconciled after its funds were settled manually. Base to Alpaca after its burn (not a deposit or conversion failure): unless the mint was reported unresolvable or funds were already moved by hand, keep the bot running and run resume-usdc base-to-alpaca, which re-polls Circle, then mints and sends. Otherwise do not mint, send or reconcile it with the bot running: the bot re-runs its recovery at every start and can send the USDC to Alpaca itself, with no check for an earlier send. Follow docs/cli-ops.md, \"Settling a post-burn Base to Alpaca failure by hand\". The offline form is stox transfer reconcile --kind usdc --id <id> --reason <funds-moved-manually|deposit-credited-offline>.", "whenToUse": "A USDC bridge failed after its funds left the source venue, and they were settled out-of-band.", "appliesTo": "USDC failure with funds off the source venue (DepositFailed, any AlpacaToBase BridgingFailed, a post-burn BaseToAlpaca BridgingFailed, or BaseToAlpaca ConversionFailed)", "mode": "requires-bot"}]}, {"object": "position", "commands": [{"command": "st0x-liquidity-client --env production debug position release-hedge <symbol> --order-id <order-id> --reason \"<reason>\"", "description": "Clear a position's pending offchain order pointer so hedging can retry.", "whenToUse": "A position is wedged on a hedge order that never resolved.", "appliesTo": "Position with a stuck pending offchain order", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug position set <symbol> --target-net <N> [--price-usdc <USDC_PER_SHARE>] --reason \"<reason>\"", "description": "Override a position\u2019s net exposure after a manual correction. The target is signed: negative is short, 0 is flat.", "whenToUse": "The recorded net exposure has drifted from reality and must be set explicitly.", "appliesTo": "Any position", "mode": "requires-bot"}]}, {"object": "view", "commands": [{"command": "st0x-liquidity-client --env production debug view rebuild <position|offchain-order|vault-registry> (--id <id> | --all)", "description": "Replay all events to reconstruct a corrupted materialized view.", "whenToUse": "A view became corrupted (e.g. lost updates from optimistic-lock conflicts).", "appliesTo": "Position / offchain-order / vault-registry views", "mode": "requires-bot"}]}, {"object": "cctp", "commands": [{"command": "st0x-liquidity-client --env production debug cctp complete-mint --burn-tx <hash> --source-chain <ethereum|base>", "description": "Complete the destination-chain mint of a stuck CCTP transfer. A burn Circle has not attested yet fails at once as retryable; rerun it later. If the burn belongs to a stuck USDC bridge, run resume-usdc afterwards while the bridge is not terminal. Run reconcile-usdc only after a terminal failure whose funds leg is done and verified at the destination. For a Base to Alpaca bridge that failed after its burn, follow docs/cli-ops.md, \"Settling a post-burn Base to Alpaca failure by hand\", instead.", "whenToUse": "A CCTP burn succeeded but attestation polling was interrupted before the mint.", "appliesTo": "CCTP cross-chain USDC transfer", "mode": "requires-bot"}]}, {"object": "trade", "commands": [{"command": "st0x-liquidity-client --env production debug process-tx <hash> [--chain <base|ethereum|hyperevm|robinhood>]", "description": "Re-account a missed onchain fill: record the trade and place the hedge.", "whenToUse": "The bot missed an onchain fill and the position/hedge was never updated.", "appliesTo": "Onchain (Raindex) fills", "mode": "requires-bot"}]}]};

// The operations client a board command runs with: the client form of the
// SPA's LIQUIDITY_CLIENT and forClientEnv (dashboard/src/lib/transfer.ts).
// The generator prepends this file to header.js and detail.js;
// dashboard/src/lib/transfer-board.test.ts imports it as a module through the
// export line, which the generator drops, and checks it against the SPA.

const LIQUIDITY_CLIENT = 'st0x-liquidity-client --env production';

// The board always knows its environment: the selector's text is production
// or staging. The SPA shows a placeholder when its environment is unknown.
const boardEnv = (envText) => (envText === 'staging' ? 'staging' : 'production');

const forClientEnv = (command, env) => command.replace('--env production', `--env ${env}`);

const clientFor = (envText) => forClientEnv(LIQUIDITY_CLIENT, boardEnv(envText));


// Business Text "afterRender" code for the Liquidity bot header: the SPA's
// HeaderBar and SettingsBar (header-bar.svelte, settings-bar.svelte,
// recovery-guide.svelte in ST0x-Technology/st0x.liquidity) in one row, with
// the same Config and CLI recovery guide dialogs.
//
// Input: context.data, rows with a `k` column naming the value (up, uptime,
// commit, info, equity_target, ...) plus the string labels some of them
// carry (git_commit on commit; broker, wallet_kind, ... on info).
//
// RECOVERY_GUIDE is not defined here: the generator prepends it from
// recovery-guide.json (see pills() in the generator), because the template output is
// sanitized and cannot carry data into this code.

const rows = Array.isArray(context.data) ? context.data : [];
const value = {};
const labels = {};
// The stackdriver datasource runs a range query even for an instant target,
// so each `k` can arrive at several times; keep the newest.
const seen = {};
for (const row of rows) {
  const time = Number(row.Time) || 0;
  if (row.k !== 'commit') {
    if (row.k in seen && seen[row.k] > time) continue;
    seen[row.k] = time;
  }
  if (row.k === 'commit') {
    // A range query keeps the previous commit's series for a few minutes
    // after a deploy. The commit row's value is its sample timestamp, so the
    // newest one is the running commit.
    if (!labels.commit || row.Value > labels.commit.at) labels.commit = { sha: row.git_commit, at: row.Value };
  } else if (row.k === 'info') {
    labels.info = row;
  } else {
    value[row.k] = row.Value === null || row.Value === undefined || Number.isNaN(Number(row.Value)) ? null : Number(row.Value);
  }
}
const info = labels.info || {};

const theme = context.grafana.theme;
const root = context.element;
// The guide's commands target the environment the board shows
// (client-env.js, prepended).
const ENV = boardEnv(context.grafana.replaceVariables('${env:text}'));
// The plugin pads each rendered row by 8px, which makes this one-row panel
// scroll; the row has no room for it.
root.style.padding = '0';
root.style.height = '100%';
root.style.overflow = 'hidden';
root.style.setProperty('--hdr-muted', theme.colors.text.secondary);
// Light theme swaps the mode colours for darker shades (header.css).
root.classList.toggle('hdr-light', !theme.isDark);
root.style.setProperty('--hdr-border', theme.colors.border.weak);
root.style.setProperty('--hdr-pill', theme.colors.background.secondary);
root.style.setProperty('--hdr-card', theme.colors.background.primary);
root.style.setProperty('--hdr-text', theme.colors.text.primary);

const escapeHtml = (text) =>
  String(text ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);

// The SPA's fmtPct and band strings: "50%" and "45%–55%".
const pct = (fraction) => `${(fraction * 100).toFixed(0)}%`;
const band = (target, deviation) =>
  target === null || target === undefined
    ? ''
    : deviation === null || deviation === undefined
      ? ''
      : ` <span class="hdr-muted">(${pct(target - deviation)}–${pct(target + deviation)})</span>`;

// The SPA's formatUptime.
const uptime = (seconds) => {
  if (seconds === null || seconds === undefined) return '';
  const days = Math.floor(seconds / 86400);
  const hours = Math.floor((seconds % 86400) / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  if (days > 0) return `up ${days}d ${hours}h`;
  if (hours > 0) return `up ${hours}h ${minutes}m`;
  return `up ${minutes}m`;
};

const clock = () => new Date().toISOString().replace('T', ' ').slice(0, 19) + ' UTC';

const pill = (inner) => `<span class="hdr-pill">${inner}</span>`;
// 1 up, 0 down; no value means the source is not reporting, which says
// nothing about the bot.
const connection =
  value.up === 1 ? ['hdr-ok', 'Connected'] : value.up === 0 ? ['hdr-bad', 'Disconnected'] : ['hdr-unknown', 'No data'];

const pills = [
  info.broker ? pill(`<span class="hdr-mono">${escapeHtml(info.broker)}</span>`) : '',
  value.equity_target !== null && value.equity_target !== undefined
    ? pill(`Equity <b class="hdr-mono">${pct(value.equity_target)}</b>${band(value.equity_target, value.equity_deviation)}`)
    : '',
  value.usdc_target !== null && value.usdc_target !== undefined
    ? pill(`USDC <b class="hdr-mono">${pct(value.usdc_target)}</b>${band(value.usdc_target, value.usdc_deviation)}`)
    : '',
  value.trigger !== null && value.trigger !== undefined ? pill(`Trigger <b class="hdr-mono">$${value.trigger}</b>`) : '',
  value.cash_reserved !== null && value.cash_reserved !== undefined
    ? pill(`Reserve <b class="hdr-mono">$${value.cash_reserved}</b>`)
    : '',
  '<button class="hdr-pill hdr-button" data-open="config">Config</button>',
].join('');

const configRow = (name, text) =>
  `<div class="hdr-row"><span class="hdr-muted">${name}</span><span class="hdr-mono hdr-trunc" title="${escapeHtml(text)}">${escapeHtml(text)}</span></div>`;
const seconds = (number) => (number === null || number === undefined ? '' : `${number}s`);

const configDialog = `
<dialog class="hdr-dialog hdr-narrow" data-dialog="config">
  <div class="hdr-dialog-head"><span>Configuration</span><button class="hdr-close" data-close aria-label="Close">&times;</button></div>
  <div class="hdr-dialog-body hdr-mono">
    ${
      info.wallet_kind
        ? configRow('Wallet', info.wallet_kind) +
          configRow('Address', info.wallet_address) +
          (info.wallet_kind === 'turnkey' && info.turnkey_organization ? configRow('Turnkey org', info.turnkey_organization) : '') +
          '<div class="hdr-rule"></div>'
        : ''
    }
    ${configRow('Exported log level', info.log_level)}
    ${configRow('Server port', info.server_port)}
    ${configRow('Deployment block', value.deployment_block ?? '')}
    ${configRow('Order polling', seconds(value.order_polling))}
    ${configRow('Inventory polling', seconds(value.inventory_polling))}
    ${configRow('Cash reserve', value.cash_reserved !== null && value.cash_reserved !== undefined ? `$${value.cash_reserved}` : 'none')}
    ${configRow('Orderbook', info.orderbook)}
  </div>
</dialog>`;

const guide = RECOVERY_GUIDE;
const modeClass = (mode) =>
  mode === 'requires-bot' ? 'hdr-amber' : 'hdr-red';
const guideDialog = `
<dialog class="hdr-dialog hdr-wide" data-dialog="guide">
  <div class="hdr-dialog-head"><span>CLI recovery guide</span><button class="hdr-close" data-close aria-label="Close">&times;</button></div>
  <div class="hdr-dialog-body">
    <p class="hdr-muted hdr-intro">Every recovery command, grouped by object. They use <span class="hdr-mono">st0x-liquidity-client</span>, which signs in with your Google account and calls the running bot's API, so no SSH is needed and the bot must be running. Some steps need the offline <span class="hdr-mono">stox</span> with the bot stopped instead, for example failing a USDC bridge after its nonce close (<span class="hdr-mono">stox fail-usdc-transfer</span>), and settling a Base to Alpaca bridge by hand after its burn (<span class="hdr-mono">stox transfer reconcile</span>). Each command's description says when.</p>
    ${guide.groups
      .map(
        (group) => `
      <section class="hdr-group">
        <h3 class="hdr-mono">${escapeHtml(group.object)}</h3>
        ${group.commands
          .map(
            (entry) => `
          <div class="hdr-command">
            <pre class="hdr-mono">${escapeHtml(forClientEnv(entry.command, ENV))}</pre>
            <div class="hdr-grid">
              <span class="hdr-muted">What</span><span>${escapeHtml(entry.description)}</span>
              <span class="hdr-muted">When</span><span>${escapeHtml(entry.whenToUse)}</span>
              <span class="hdr-muted">Applies to</span><span>${escapeHtml(entry.appliesTo)}</span>
              <span class="hdr-muted">Mode</span><span class="${modeClass(entry.mode)}">${escapeHtml(guide.modeLabels[entry.mode] || entry.mode)}</span>
            </div>
          </div>`
          )
          .join('')}
      </section>`
      )
      .join('')}
  </div>
</dialog>`;

// The board refreshes every minute and each render replaces the markup, which
// would close a dialog the operator is reading. Remember it to reopen it at
// the same scroll position.
const openDialog = root.querySelector('dialog[open]');
const reopen = openDialog && {
  name: openDialog.dataset.dialog,
  scroll: openDialog.querySelector('.hdr-dialog-body')?.scrollTop || 0,
};

root.innerHTML = `
<div class="hdr">
  <div class="hdr-left">${pills}</div>
  <div class="hdr-right">
    <button class="hdr-guide" data-open="guide">CLI recovery guide</button>
    <span class="hdr-mono hdr-muted" data-clock>${clock()}</span>
    ${labels.commit && labels.commit.sha ? `<span class="hdr-mono hdr-muted" title="Deployed commit">${escapeHtml(labels.commit.sha.slice(0, 7))}</span>` : ''}
    <span class="hdr-muted" title="Bot uptime">${uptime(value.uptime)}</span>
    <span class="hdr-badge ${connection[0]}">${connection[1]}</span>
  </div>
</div>
${configDialog}
${guideDialog}`;

root.querySelectorAll('[data-open]').forEach((button) => {
  button.addEventListener('click', () => root.querySelector(`[data-dialog="${button.dataset.open}"]`).showModal());
});
root.querySelectorAll('dialog').forEach((dialog) => {
  dialog.querySelector('[data-close]').addEventListener('click', () => dialog.close());
  // A click on the backdrop closes it, like the SPA.
  dialog.addEventListener('click', (event) => {
    if (event.target === dialog) dialog.close();
  });
});
if (reopen) {
  const dialog = root.querySelector(`[data-dialog="${reopen.name}"]`);
  if (dialog) {
    dialog.showModal();
    const body = dialog.querySelector('.hdr-dialog-body');
    if (body) body.scrollTop = reopen.scroll;
  }
}

// The SPA's ticking UTC clock. One interval per element, replaced on every
// render so a refresh never stacks them. Grafana can also mount a new
// element (tab switch, view mode), so an interval whose element left the
// page stops itself.
clearInterval(root.__hdrClock);
root.__hdrClock = setInterval(() => {
  if (!root.isConnected) {
    clearInterval(root.__hdrClock);
    return;
  }
  const node = root.querySelector('[data-clock]');
  if (node) node.textContent = clock();
}, 1000);

options.styles:
/* Business Text "styles" for the Liquidity bot header row and its two
   dialogs. Theme colours come in as --hdr-* variables set by header.js. */

.hdr {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  height: 100%;
  font-size: 13px;
  white-space: nowrap;
}

.hdr-left,
.hdr-right {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.hdr-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 10px;
  border-radius: 9999px;
  background: var(--hdr-pill);
  color: var(--hdr-text);
  font-size: 13px;
  line-height: 18px;
  border: 0;
}

.hdr-button {
  color: var(--hdr-muted);
  cursor: pointer;
}

.hdr-button:hover,
.hdr-guide:hover,
.hdr-close:hover {
  color: var(--hdr-text);
}

.hdr-guide {
  padding: 2px 8px;
  border: 1px solid var(--hdr-border);
  border-radius: 4px;
  background: transparent;
  color: var(--hdr-text);
  font-size: 13px;
  line-height: 18px;
  cursor: pointer;
}

.hdr-badge {
  padding: 2px 8px;
  border-radius: 9999px;
  font-size: 13px;
  line-height: 18px;
  font-weight: 600;
}

.hdr-ok { background: #f5f5f5; color: #171717; }
.hdr-bad { background: #ef4444; color: #fff; }
.hdr-unknown { border: 1px solid var(--hdr-border); color: var(--hdr-muted); }

.hdr-mono { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }
.hdr-muted { color: var(--hdr-muted); }

.hdr-dialog {
  padding: 0;
  border: 1px solid var(--hdr-border);
  border-radius: 8px;
  background: var(--hdr-card);
  color: var(--hdr-text);
  white-space: normal;
}

.hdr-dialog::backdrop { background: rgba(0, 0, 0, 0.5); }
.hdr-narrow { width: min(28rem, 92vw); }
.hdr-wide { width: min(42rem, 92vw); }

.hdr-dialog-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-bottom: 1px solid var(--hdr-border);
  font-size: 14px;
  font-weight: 600;
}

.hdr-close {
  border: 0;
  background: transparent;
  color: var(--hdr-muted);
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
}

.hdr-dialog-body {
  max-height: 70vh;
  overflow-y: auto;
  padding: 16px 20px;
  font-size: 13px;
}

.hdr-row {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 4px 0;
}

.hdr-trunc {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hdr-rule { border-top: 1px solid var(--hdr-border); margin: 8px 0; }
.hdr-intro { margin: 0 0 16px; }
.hdr-group { margin-bottom: 20px; }
.hdr-group h3 { margin: 0 0 8px; font-size: 13px; text-transform: capitalize; }

.hdr-command {
  margin-bottom: 12px;
  padding: 8px 12px;
  border: 1px solid var(--hdr-border);
  border-radius: 6px;
  background: var(--hdr-pill);
}

.hdr-command pre {
  margin: 0;
  padding: 8px;
  border-radius: 4px;
  background: var(--hdr-card);
  font-size: 12px;
  white-space: pre-wrap;
  word-break: break-all;
}

.hdr-grid {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  margin-top: 6px;
  font-size: 12px;
}

.hdr-amber { color: #f59e0b; }
.hdr-red { color: #ef4444; }

/* Tailwind 700 on the light theme, like detail.css, for a 4.5:1 contrast
   against the white dialog. */
.hdr-light .hdr-amber { color: #b45309; }
.hdr-light .hdr-red { color: #b91c1c; }

options.afterRender:
const MODE_LABELS = {"requires-bot": "REST \u2014 requires the running bot", "direct-db": "direct DB \u2014 stop the bot / ensure it is not driving this id"};

// The operations client a board command runs with: the client form of the
// SPA's LIQUIDITY_CLIENT and forClientEnv (dashboard/src/lib/transfer.ts).
// The generator prepends this file to header.js and detail.js;
