// usdcResumeNote in transfer.ts: the extra resume text for a bridge's status
// and direction.
const usdcResumeNote = (status, direction) => {
  if (direction === 'base_to_alpaca' && status === 'bridging') return USDC_BRIDGING_BASE_TO_ALPACA;
  if (direction !== 'base_to_alpaca' && status === 'converting') return USDC_CONVERTING_ALPACA_TO_BASE;
  return '';
};

// usdcFailCheck in transfer.ts: the check before fail-usdc-transfer, or null
// where the running bot always refuses it.
const usdcFailCheck = (status, direction) => {
  if (direction === 'alpaca_to_base') {
    return status === 'withdrawing' || status === 'bridging' ? USDC_FAIL_ALPACA_TO_BASE : null;
  }
  if (direction === 'base_to_alpaca') return status === 'withdrawing' ? USDC_FAIL_BASE_TO_ALPACA : null;
  return status === 'withdrawing' || status === 'bridging'
    ? `${USDC_FAIL_ALPACA_TO_BASE} ${USDC_FAIL_BASE_TO_ALPACA}`
    : null;
};

const transferCommands = (client, transfer) => {
  const status = String(transfer.status || '').toLowerCase();
  const failed = status === 'failed';
  const terminal = failed || status === 'completed' || status === 'reconciled';
  if (status === 'completed' || status === 'reconciled') return [];
  const id = transfer.id;

  if (transfer.kind === 'usdc_bridge') {
    // Reconcile needs the bridge's postBurn flag, which the exporter does not
    // log; the SPA offers nothing without it either.
    if (failed) return [];
    const direction =
      { alpaca_to_base: 'alpaca-to-base', base_to_alpaca: 'base-to-alpaca' }[transfer.direction] ||
      '<alpaca-to-base|base-to-alpaca>';
    const resume = {
      command: `${client} debug resume-usdc ${direction} ${id}`,
      description:
        "Re-drive this USDC bridge on the bot's transfer worker from the stage it stopped at." +
        usdcResumeNote(status, transfer.direction || null),
      mode: 'requires-bot',
    };
    const check = usdcFailCheck(status, transfer.direction || null);
    if (check === null) return [resume];
    return [
      resume,
      {
        command: `${client} debug fail-usdc-transfer ${id} --reason "<reason>"`,
        description: `Check the transfer first. ${check}`,
        mode: 'requires-bot',
      },
    ];
  }

  const kind = { equity_mint: 'mint', equity_redemption: 'redemption' }[transfer.kind];
  if (!kind) return [];
  const commands = [
    {
      command: `${client} debug recheck ${kind} ${id}`,
      description: 'Ask the running bot to re-poll the provider and complete the transfer if it settled.',
      mode: 'requires-bot',
    },
  ];
  if (!terminal) {
    commands.push({
      command: `${client} debug resume`,
      description:
        'Re-drive ALL interrupted mints and redemptions via the bot (no id; best-effort per transfer, each succeeds or fails independently and failures are reported as counts).',
      mode: 'requires-bot',
    });
    commands.push({
      command: `${client} debug fail-equity-transfer ${kind} ${id} --reason "<reason>"`,
      description: 'Force this stuck transfer into the terminal Failed state. Use when it is permanently stuck.',
      mode: 'requires-bot',
    });
  }
  if (failed) {
    commands.push({
      command: `${client} debug reconcile-equity ${kind} ${id} --reason "<reason>"`,
      description:
        'Mark a Failed transfer as Reconciled once its residue was handled out-of-band (bookkeeping).' +
        (kind === 'redemption' ? EQUITY_RECONCILE_INFLIGHT : ''),
      mode: 'requires-bot',
    });
  }
  return commands;
};


// The detail dialog's status history: a Trades or Rebalances row's status-log
// entries in order, and the status the row is at. The generator prepends this
// file to detail.js; dashboard/src/lib/transfer-board.test.ts imports it as a
// module through the export line, which the generator drops.

// A USDC bridge's in-flight statuses in lifecycle order per direction. Their
// log times can go backwards (WithdrawalComplete carries confirmed_at, the
// BridgingSubmitting after it the older initiated_at), so two in-flight
// entries of a bridge are ordered by this. Anything else, failed included
// (the bot can recover a bridge out of a failure), orders by time.
//
// Known limit: a Base to Alpaca bridge recovered out of DepositFailed reaches
// converting, which the bot stamps with the bridge's initiated_at. That entry
// sorts before the failed one, so the dialog keeps showing the status before
// it (failed, or depositing) until the bridge completes.
const BRIDGE_LIFECYCLE = {
  alpaca_to_base: ['converting', 'withdrawing', 'bridging', 'depositing'],
  base_to_alpaca: ['withdrawing', 'bridging', 'depositing', 'converting'],
};
const stage = (entry) => {
  const lifecycle = entry.kind === 'usdc_bridge' ? BRIDGE_LIFECYCLE[entry.direction] : null;
  const index = lifecycle ? lifecycle.indexOf(String(entry.status || '').toLowerCase()) : -1;
  return index >= 0 ? index : null;
};

// The event store's sequence in a bot line's `event_id`
// (`<aggregate>:<id>:<sequence>`), or null for an exporter entry.
const sequenceOf = (entry) => {
  const match = /:(\d+)$/.exec(entry.event_id || '');
  return match ? Number(match[1]) : null;
};

// The row at its latest status, with its status history oldest first. The
// bot's lines carry the commit order, so they sort by sequence. Exporter
// entries sort by time (ties keep Cloud Logging's newest-first order
// reversed), then each pair of neighbouring in-flight bridge entries is put
// in lifecycle order.
const latest = (entries) => {
  if (entries.length === 0) return null;
  if (entries.every((entry) => sequenceOf(entry) !== null)) {
    const history = [...entries].sort((left, right) => sequenceOf(left) - sequenceOf(right));
    const last = history[history.length - 1];
    return { ...last, first: Math.min(...entries.map((entry) => entry.time)), history };
  }
  const history = [...entries].reverse().sort((left, right) => left.time - right.time);
  for (let swapped = true; swapped; ) {
    swapped = false;
    for (let index = 1; index < history.length; index++) {
      const [before, after] = [stage(history[index - 1]), stage(history[index])];
      if (before !== null && after !== null && before > after) {
        [history[index - 1], history[index]] = [history[index], history[index - 1]];
        swapped = true;
      }
    }
  }
  const last = history[history.length - 1];
  return { ...last, first: Math.min(...entries.map((entry) => entry.time)), history };
};


// The detail dialog's reading of Cloud Logging frames: a row's entries, and
// the bot's event timeline. The generator prepends this file to detail.js;
// dashboard/src/lib/transfer-board.test.ts imports it as a module through
// the export line, which the generator drops.

// A JSON object, or null for anything else (no value, bad JSON, a string).
const parseObject = (value) => {
  if (value !== null && typeof value === 'object') return value;
  try {
    const parsed = JSON.parse(value);
    return parsed !== null && typeof parsed === 'object' ? parsed : null;
  } catch (error) {
    return null;
  }
};

// The entries of `id` in one frame of the plugin's log-lines shape, newest
// first like the frame: each line's time and payload. The exporter's body
// is its JSON payload. A bot line's body is its message, so its payload
// comes from the flattened `jsonPayload.<key>` labels, which the exporter's
// lines carry too. A line from another project than `project` belongs to
// the environment the board showed before a switch and is dropped. A line
// whose `event_id` came before (the bot's lines, shipped twice) is dropped.
const lineEntries = (frame, id, project) => {
  if (!frame) return [];
  const column = (name) => frame.fields.find((field) => field.name === name);
  const times = column('timestamp');
  const bodies = column('body');
  const labels = column('labels');
  const count = times ? times.values.length : 0;
  const seen = new Set();
  const entries = [];
  for (let index = 0; index < count; index++) {
    const flat = (labels && parseObject(labels.values[index])) || {};
    const lineProject = flat['resource.labels.project_id'];
    if (lineProject && lineProject !== project) continue;
    const fromLabels = {};
    for (const [key, value] of Object.entries(flat)) {
      if (key.startsWith('jsonPayload.')) fromLabels[key.slice('jsonPayload.'.length)] = value;
    }
    const payload = (bodies && parseObject(bodies.values[index])) || fromLabels;
    if (!payload.id || String(payload.id) !== id) continue;
    if (payload.event_id) {
      if (seen.has(payload.event_id)) continue;
      seen.add(payload.event_id);
    }
    entries.push({ time: Number(times.values[index]), ...payload });
  }
  return entries;
};

// A row's event timeline from its liq_event entries, oldest first: the
// events of a trade, or of a transfer of `kind` (each transfer kind is its
// own aggregate). A trade's events are not matched on venue, because a
// venue correction changes it. Each payload is parsed from its JSON string.
const eventTimeline = (entries, parent, kind) =>
  entries
    .filter((entry) => entry.parent === parent && (parent !== 'transfer' || entry.kind === kind))
    .map((entry) => ({ ...entry, payload: parseObject(entry.payload) || {} }))
    .sort((left, right) => Number(left.sequence) - Number(right.sequence));

// Whether a row's event timeline misses events: the event store numbers an
// aggregate's events from 1 without gaps, so a timeline that does not start
// at 1, skips a number, or ends before the event of the row's latest status
// line (`rowEventId`, `<aggregate>:<id>:<sequence>`) lacks lines: lines not
// loaded yet (the events scan ran before the row's), the newest-500 window,
// or a line the bot never wrote.
const timelineIncomplete = (events, rowEventId) => {
  const match = /:(\d+)$/.exec(rowEventId || '');
  const last = events.length > 0 ? Number(events[events.length - 1].sequence) : 0;
  return (
    events.some((event, index) => Number(event.sequence) !== index + 1) ||
    (match !== null && Number(match[1]) > last)
  );
};

// The panel errors that concern the source shown. A failed query of the
// other source, or of the event timeline, leaves the rows usable, so it does
// not block them. An error without a refId blocks: it cannot be placed.
const blockingErrors = (errors, source) => {
  const other = source === 'bot' ? 'exporter-' : 'bot-';
  return errors.filter(
    (error) => !error.refId || (error.refId !== 'bot-events' && !error.refId.startsWith(other))
  );
};

// What the panel's last refresh says about the queries the source shown
// reads. Grafana's Mixed datasource keeps only the last failing query's
// errors (runRequest's processResponsePacket overwrites error and errors per
// packet), so an Error state whose listed errors do not block can still hide
// a failed table query, and its frames can be the ones the failed refresh
// kept. `failed`: a listed error blocks, or the state is Error with none
// listed. `unsure`: the state is Error and only errors that do not block are
// listed, so a row shown can be out of date. `eventsFailed`: the event query
// is among the listed errors, whether Grafana gave a list or one error.
const queryState = (panelData, source) => {
  const listed = panelData?.errors || (panelData?.error ? [panelData.error] : []);
  const blocking = blockingErrors(listed, source);
  const isError = panelData?.state === 'Error';
  return {
    listed,
    blocking,
    failed: isError && (listed.length === 0 || blocking.length > 0),
    unsure: isError && listed.length > 0 && blocking.length === 0,
    eventsFailed: listed.some((error) => error.refId === 'bot-events'),
  };
};



